const checks = ['Check bapm run','Check ai run','Check marketing run'];
const repos = ['ba-pm-jobs-internships','ai-automation-jobs-internships','marketing-jobs-internships'];
// UTC snapshot date, matching the refresh workflow's UTC dating.
const today = new Date().toISOString().slice(0,10);
const results = [];
let ok = true;
for (let i = 0; i < checks.length; i++) {
  const items = $items(checks[i]);
  const body = (items[0] && items[0].json) || {};
  // F7: a failed/limited GitHub API response has no workflow_runs array (e.g. a 403
  // rate-limit JSON body still arrives as a "successful" HTTP node). That is a
  // MONITOR-SOURCE error, not evidence about the refresh - never report it as a
  // refresh failure. An empty array is real data: no scheduled runs match today.
  const sourceError = !Array.isArray(body.workflow_runs);
  const runs = sourceError ? [] : body.workflow_runs;
  // The HTTP nodes ask the API for branch=main&event=schedule&created=<UTC day>&per_page=30:
  // only today's scheduled runs are fetched, so manual dispatch volume can never push the
  // scheduled run off the page. Evaluator-side date/event/branch checks retained anyway.
  const sched = runs.filter(r => r.head_branch === 'main' && r.event === 'schedule')
    .filter(r => String(r.created_at||'').slice(0,10) === today);
  // F7b (reviewer): remaining possible truncation = total_count beyond the returned page
  // (GitHub signals further pages via the Link header, which this node does not see, so
  // total_count vs returned rows is the bounded-completion proof available here).
  // Absence of a successful scheduled run is PROVEN only when the page is complete.
  // A truncated page without a proven success is incomplete_coverage, never a proven absence.
  // This is an existence-only monitor: one matching success is sufficient proof of green.
  const total = typeof body.total_count === 'number' ? body.total_count : runs.length;
  const truncated = !sourceError && total > runs.length;
  const goodRun = sched.find(r => r.status === 'completed' && r.conclusion === 'success');
  const latest = sched[0] || null;
  const good = Boolean(goodRun);
  // Four-valued verdict. ok = proven success today. refresh_not_green = complete page,
  // proven no successful scheduled run yet (missing/failed/in-progress). source_error =
  // monitor could not read GitHub at all. source_inconclusive = page truncated and no
  // proven success - absence not established. ok stays false except for proven success.
  const verdict = sourceError ? 'source_error'
    : (good ? 'ok' : (truncated ? 'incomplete_coverage' : 'refresh_not_green'));
  if (!good) ok = false;
  results.push({
    repo: repos[i],
    verdict,
    source_error: sourceError,
    source_error_body: sourceError ? { message: body.message || null, documentation_url: body.documentation_url || null } : undefined,
    page_truncated: truncated,
    total_count: total,
    scheduled_runs_today: sched.length,
    good,
    latest_scheduled_today: latest ? { status: latest.status, conclusion: latest.conclusion, event: latest.event, head_branch: latest.head_branch, created_at: latest.created_at, url: latest.html_url } : null,
    scheduled_today: sched.map(r => ({ status: r.status, conclusion: r.conclusion, created_at: r.created_at, url: r.html_url }))
  });
}
const summary = { date_utc: today, ok, results, note: 'Career refresh monitor: each site needs a SUCCESSFUL SCHEDULE-EVENT main-branch refresh run today (UTC). The GitHub query is pre-filtered branch=main&event=schedule&created=<UTC day>&per_page=30, so manual dispatch volume cannot hide the scheduled run and manual success never satisfies the check. verdict=source_error: the monitor itself could not read the GitHub API (rate limit/network) - inconclusive about the refresh, NOT a refresh failure. verdict=incomplete_coverage: total_count exceeds the returned page and no success is proven - absence not established, never reported as a refresh failure. Run-success monitoring only; it does not validate published snapshot content.' };
console.log(JSON.stringify(summary));
return [{ json: summary }];
